CREATE OR REPLACE FUNCTION public.company_module_access(_company uuid,_module text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; state text; BEGIN SELECT id,status INTO sid,state FROM public.platform_subscriptions WHERE company_id=_company AND product_id=public.company_app_product_id() LIMIT 1; IF NOT FOUND OR state='legacy' THEN RETURN true; END IF; RETURN public.platform_subscription_module_access(sid,CASE WHEN _module IN('customer_quotes','contracts') THEN 'core' ELSE _module END); END $$;
CREATE OR REPLACE FUNCTION public.guard_ppm_equipment_dates() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x public.agreement_assets; BEGIN IF EXISTS(SELECT 1 FROM public.agreement_assets WHERE agreement_id=NEW.agreement_id) THEN SELECT * INTO x FROM public.agreement_assets WHERE agreement_id=NEW.agreement_id AND asset_id=NEW.asset_id AND company_id=NEW.company_id; IF x.id IS NULL OR NEW.interval_months<>x.interval_months OR NOT (NEW.first_due_date BETWEEN x.start_date AND x.end_date OR EXISTS(SELECT 1 FROM jsonb_array_elements(x.renewal_history) z WHERE NEW.first_due_date BETWEEN (z->>'start')::date AND (z->>'end')::date)) THEN RAISE EXCEPTION 'Maintenance schedule must match this covered equipment and its dates'; END IF; END IF; RETURN NEW; END $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.guard_ppm_plan()'::regprocedure) INTO d; d=replace(d,'IF NEW.first_due_date<a.start_date OR NEW.first_due_date>a.end_date OR a.end_date>NEW.first_due_date+interval ''5 years'' THEN','IF (TG_OP=''INSERT'' AND (NEW.first_due_date<a.start_date OR NEW.first_due_date>a.end_date)) OR a.end_date>NEW.first_due_date+interval ''5 years'' THEN'); EXECUTE d; END $$;